INSERT INTO scheduled_tasks (id, agent_id, name, description, schedule_type, cron_expression, action, action_params, status, last_run, next_run, run_count, fail_count, created_at, enabled) VALUES
('cio-daily-scan', 'cio-intelligence', 'Daily Intelligence Scan', 'Scan external sources for relevant signals, filter noise vs signal', 'cron', '0 7 * * *', 'custom_prompt', '{"prompt":"Execute Daily Intelligence Scan. Step 1: Scan news sources for breaking developments in user''s domains. Step 2: Check Reddit for sentiment shifts on relevant topics. Step 3: Query academic sources (arXiv, Semantic Scholar) for new papers in relevant fields. Step 4: Run trending entity detection for emerging topics. Step 5: Apply signal vs noise filter — relevance (affects user''s domains?), impact (consequence if ignored?), urgency (needs action now?), credibility (source reliable?). Step 6: Cross-reference findings with internal context (projects, quarterly_goals). Produce: 1) Daily signal summary — count of signals detected, top signals requiring attention, 2) Noise report — what was filtered out and why, 3) Breaking alerts — any developments needing immediate flagging to relevant agents, 4) Research updates — new papers/findings relevant to user''s work. If no significant signals detected: reply HEARTBEAT_OK. If signals detected: produce brief with prioritized intelligence.","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cio-weekly-digest', 'cio-intelligence', 'Weekly Intelligence Digest', 'Weekly intelligence aggregation with trend trajectory analysis', 'cron', '0 16 * * 0', 'custom_prompt', '{"prompt":"Execute Weekly Intelligence Digest. Step 1: Aggregate all intelligence findings from the past week. Step 2: Analyze trend trajectories — which topics are gaining traction, which are declining? Step 3: Cross-reference weekly intelligence with internal operations (COO productivity, CMO content, CFO financial, CRO relational). Step 4: Identify emerging patterns that span multiple domains. Step 5: Assess competitive landscape — what are competitors/peers doing? Step 6: Generate weekly intelligence digest. Produce: 1) Weekly intelligence report — signals detected, trends identified, emerging patterns, 2) Trend trajectory assessment — gaining momentum, stable, declining topics, 3) Cross-domain correlation — how external intelligence affects internal operations, 4) Competitive intelligence — notable competitor/peer developments, 5) Next week watchlist — topics to monitor closely. Save weekly intelligence digest to reports DB via lifeos_create_entry(database=''reports''). SYSTEMIC FLAG CHECK: If trend detected that significantly affects user''s strategic position or competitive landscape → send message.send to ceo-strategic with intelligence pattern flag. Do NOT write to systemic_journal.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cio-monthly-synthesis', 'cio-intelligence', 'Monthly Intelligence Synthesis', 'Monthly intelligence synthesis with landscape analysis and early warning', 'cron', '0 14 L * *', 'custom_prompt', '{"prompt":"Execute Monthly Intelligence Synthesis. Step 1: Aggregate all intelligence findings from the past month. Step 2: Generate comprehensive external landscape analysis — what has changed, what has stayed constant. Step 3: Assess trend trajectories at monthly scale — are identified trends accelerating, stabilizing, or reversing? Step 4: Identify early warning signals — what emerging developments need attention next month? Step 5: Correlate external intelligence with internal performance across all domains (COO/CPO/CFO/CMO/CRO). Step 6: Generate monthly intelligence synthesis report. Produce: 1) Monthly landscape report — major shifts, constant factors, emerging developments, 2) Trend trajectory analysis — acceleration/deceleration of key trends, 3) Early warning detection — signals requiring attention next month, 4) Cross-domain impact assessment — how external environment affected internal operations, 5) Strategic implications — what this means for user''s goals and strategy. Save comprehensive monthly intelligence report to reports DB. SYSTEMIC FLAG CHECK: If paradigm shift detected in user''s industry/domain, or emerging threat with strategic implications → send message.send to ceo-strategic with systemic intelligence pattern flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cio-quarterly-review', 'cio-intelligence', 'Quarterly Strategic Intelligence Review', 'Quarterly strategic intelligence review with paradigm shift detection', 'cron', '0 11 1 1,4,7,10 *', 'custom_prompt', '{"prompt":"Execute Quarterly Strategic Intelligence Review. Step 1: Aggregate all intelligence findings from the past quarter. Step 2: Assess strategic intelligence alignment — how has external environment shifted relative to quarterly goals? Step 3: Detect paradigm shifts — any fundamental changes in user''s operating environment? Step 4: Update opportunity landscape — new external opportunities aligned with annual themes? Step 5: Update risk landscape — how has external risk profile evolved? Step 6: Generate strategic intelligence posture assessment. Produce: 1) Quarterly intelligence report — landscape shifts, paradigm changes, opportunity/risk updates, 2) Paradigm shift analysis — fundamental environmental changes, implications for strategy, 3) Opportunity assessment — new external opportunities aligned with annual/quarterly goals, 4) Risk landscape update — evolved threat profile, emerging vulnerabilities, 5) Strategic recommendations — how to adapt strategy based on external intelligence. Save comprehensive quarterly intelligence report to reports DB. SYSTEMIC FLAG CHECK: If paradigm shift detected requiring strategic recalibration, or critical external threat emerging, or major strategic opportunity identified → send message.send to ceo-strategic with critical intelligence pattern flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1);
